CREATE TABLE app_user (id UUID PRIMARY KEY, name VARCHAR(120) NOT NULL, login VARCHAR(120) UNIQUE NOT NULL, password_hash VARCHAR(100) NOT NULL, role VARCHAR(20) NOT NULL CHECK(role IN ('ADMIN','TECNICO','SOLICITANTE')), active BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE user_session (token_hash VARCHAR(64) PRIMARY KEY, user_id UUID NOT NULL REFERENCES app_user(id), csrf VARCHAR(64) NOT NULL, expires_at TIMESTAMP WITH TIME ZONE NOT NULL);
CREATE TABLE login_attempt (attempt_key VARCHAR(64) PRIMARY KEY, failures INTEGER NOT NULL, window_start TIMESTAMP WITH TIME ZONE NOT NULL);
CREATE TABLE device (id UUID PRIMARY KEY, name VARCHAR(120) NOT NULL, os VARCHAR(200) NOT NULL DEFAULT '', location VARCHAR(120) NOT NULL, department VARCHAR(120) NOT NULL, owner_id UUID REFERENCES app_user(id), agent_hash VARCHAR(64) UNIQUE, enrollment_hash VARCHAR(64) UNIQUE, enrollment_expires TIMESTAMP WITH TIME ZONE, revoked BOOLEAN NOT NULL DEFAULT FALSE, last_seen TIMESTAMP WITH TIME ZONE, mesh_node VARCHAR(140) UNIQUE);
CREATE TABLE device_permission (device_id UUID NOT NULL REFERENCES device(id), user_id UUID NOT NULL REFERENCES app_user(id), can_control BOOLEAN NOT NULL DEFAULT FALSE, PRIMARY KEY(device_id,user_id));
CREATE TABLE ticket (id UUID PRIMARY KEY, title VARCHAR(200) NOT NULL, description VARCHAR(8000) NOT NULL, category VARCHAR(80) NOT NULL, priority VARCHAR(20) NOT NULL CHECK(priority IN ('BAIXA','NORMAL','ALTA','URGENTE')), status VARCHAR(30) NOT NULL CHECK(status IN ('ABERTO','EM_ATENDIMENTO','AGUARDANDO','RESOLVIDO')), requester_id UUID NOT NULL REFERENCES app_user(id), technician_id UUID REFERENCES app_user(id), device_id UUID REFERENCES device(id), created_at TIMESTAMP WITH TIME ZONE NOT NULL);
CREATE TABLE ticket_event (id UUID PRIMARY KEY, ticket_id UUID NOT NULL REFERENCES ticket(id), actor_id UUID NOT NULL REFERENCES app_user(id), kind VARCHAR(30) NOT NULL, body VARCHAR(8000) NOT NULL, created_at TIMESTAMP WITH TIME ZONE NOT NULL);
CREATE TABLE remote_session (id UUID PRIMARY KEY, device_id UUID NOT NULL REFERENCES device(id), technician_id UUID NOT NULL REFERENCES app_user(id), user_token_hash VARCHAR(64) NOT NULL, ticket_id UUID REFERENCES ticket(id), mode VARCHAR(10) NOT NULL CHECK(mode IN ('VIEW','CONTROL')), status VARCHAR(30) NOT NULL, requested_at TIMESTAMP WITH TIME ZONE NOT NULL, expires_at TIMESTAMP WITH TIME ZONE NOT NULL, ended_at TIMESTAMP WITH TIME ZONE, share_id VARCHAR(200), result VARCHAR(100));
CREATE INDEX session_device_idx ON remote_session(device_id,status);
CREATE INDEX ticket_requester_idx ON ticket(requester_id,created_at);
CREATE TABLE audit_event (id UUID PRIMARY KEY, actor VARCHAR(80) NOT NULL, action VARCHAR(60) NOT NULL, resource_id VARCHAR(80) NOT NULL, created_at TIMESTAMP WITH TIME ZONE NOT NULL);
